/*
 * asteroid-ephem.js — 四小行星（谷神／智神／婚神／灶神）＋凯龙 地心视黄经
 * 用法不变：window.asteroidEphem(utcDate) → {ceres:{L,rx}, pallas, juno, vesta, chiron}；超出 1900-01-01～2099-12-31 时该星返回 null。
 *
 * 数据：NASA JPL Horizons（公有领域）地心视黄经（当日黄道，含光行时、光行差、章动），1899-12-01～2100-02-01 每天 UT 0 点，
 *       每 10 天（凯龙 20 天）取一点，千分之一度存相邻差；这里用四点拉格朗日插值还原，逆行看插值曲线的斜率。
 * 精度：插值＋取整误差，对 JPL 逐日核对最大约半角分（智神 28″）；对瑞士星历另核过。
 * 换掉的旧版：astsakai/js_astro（MIT）的轨道根数推算，对瑞士星历差到 36′（婚神），落座会错。
 * 生成：build_asteroid_ephem.py（2026-10-11），别手改数据串。
 */
;(function (root) {
  var JD0 = 2414989.5;   // 1899-12-01 0h UT（跟数据第一行对齐）
  var SRC = {
    ceres: [10, 258327, ''],
    pallas: [10, 247511, ''],
    juno: [10, 280350, ''],
    vesta: [10, 13992, ''],
    chiron: [20, 255291, ''],
  };
  var TAB = {};
  function b64(s) {   // 自带解码：接口在 vm 沙盒里跑，没有 atob 也没有 Buffer
    var A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/', M = {}, i;
    for (i = 0; i < 64; i++) M[A.charAt(i)] = i;
    var pad = s.charAt(s.length - 1) === '=' ? (s.charAt(s.length - 2) === '=' ? 2 : 1) : 0;
    var u = new Uint8Array(s.length / 4 * 3 - pad), o = 0;
    for (i = 0; i < s.length; i += 4) {
      var n = (M[s.charAt(i)] << 18) | (M[s.charAt(i + 1)] << 12) | ((M[s.charAt(i + 2)] || 0) << 6) | (M[s.charAt(i + 3)] || 0);
      if (o < u.length) u[o++] = (n >> 16) & 255;
      if (o < u.length) u[o++] = (n >> 8) & 255;
      if (o < u.length) u[o++] = n & 255;
    }
    return u;
  }
  function table(n) {   // 第一次用到时才解开：连续黄经（度）
    if (TAB[n]) return TAB[n];
    var src = SRC[n], h = src[0], u = b64(src[2]), dv = new DataView(u.buffer, u.byteOffset, u.byteLength);
    var cnt = u.byteLength / 2, v = new Float64Array(cnt + 1), m = src[1];
    v[0] = m / 1000;
    for (var i = 0; i < cnt; i++) { m += dv.getInt16(i * 2, true); v[i + 1] = m / 1000; }
    return (TAB[n] = { h: h, v: v });
  }
  function at(n, jd) {
    var T = table(n), h = T.h, v = T.v, t = (jd - JD0) / h, k = Math.floor(t) - 1;
    if (k < 0 || k + 3 >= v.length) return null;
    var u = t - k, y0 = v[k], y1 = v[k + 1], y2 = v[k + 2], y3 = v[k + 3];
    var L = -(u - 1) * (u - 2) * (u - 3) / 6 * y0 + u * (u - 2) * (u - 3) / 2 * y1 - u * (u - 1) * (u - 3) / 2 * y2 + u * (u - 1) * (u - 2) / 6 * y3;
    // 斜率（对 u 求导）：负的＝逆行
    var dL = -((u - 2) * (u - 3) + (u - 1) * (u - 3) + (u - 1) * (u - 2)) / 6 * y0
           + ((u - 2) * (u - 3) + u * (u - 3) + u * (u - 2)) / 2 * y1
           - ((u - 1) * (u - 3) + u * (u - 3) + u * (u - 1)) / 2 * y2
           + ((u - 1) * (u - 2) + u * (u - 2) + u * (u - 1)) / 6 * y3;
    L = L % 360; if (L < 0) L += 360;
    return { L: L, rx: dL < 0 };
  }
  var LO = Date.UTC(1900, 0, 1), HI = Date.UTC(2100, 0, 1);
  root.asteroidEphem = function (utcDate) {
    if (!(utcDate instanceof Date) || isNaN(utcDate.getTime())) throw new Error('[asteroid-ephem] 需要有效UTC Date');
    var ms = utcDate.getTime(), ok = ms >= LO && ms < HI, jd = ms / 86400000 + 2440587.5;
    function g(n) { return ok ? at(n, jd) : null; }
    return { ceres: g('ceres'), pallas: g('pallas'), juno: g('juno'), vesta: g('vesta'), chiron: g('chiron') };
  };
})(typeof window !== 'undefined' ? window : this);
